wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // The contract guarantees `len(question) <= 512` on every input, so the
        // body does not re-check it.
        let system = format!(
            "You are a customer-support agent handling a {} request. \
             Answer the user's question using the provided knowledge. \
             If you need more information, call the `lookup` tool with a query; \
             otherwise reply with the final answer text.",
            intent_label(ctx.intent)
        );

        // Build the initial material from the attenuated context: the bounded
        // question plus whatever knowledge was handed in.
        let mut prompt = String::new();
        if ctx.knowledge.is_empty() {
            prompt.push_str("Knowledge: (none provided)\n");
        } else {
            prompt.push_str("Knowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }
        prompt.push_str("\nQuestion: ");
        prompt.push_str(&ctx.question);

        // Bounded tool-orchestration loop. The model either answers (`text`) or
        // asks for a tool (`call`). The only tool this node can honour is
        // `lookup`, because `kb-read` is the only tool interface in its world; a
        // request for anything else is an error value, not an escape.
        const MAX_ROUNDS: u32 = 4;
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(&system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nResults of lookup(\"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\"):\n");
                        if results.is_empty() {
                            prompt.push_str("(no matching entries)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        return ResponseResult::Error(LlmError {
                            message: format!(
                                "requested tool '{}' is not in this node's scope",
                                req.tool
                            ),
                        });
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge within bound".to_string(),
        })
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "general",
    }
}

export!(Node);
```

